def refs():
    return [{**s, "subject": "science", "locator": "原子模型、元素特性、金屬導電與延展、原子重新排列及微觀模型判讀", "observedPattern": "公開學校理化試題常以粒子模型、元素特性與生活材料情境，要求由可觀察性質判斷微觀結構；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-cb-iv-2-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": "A", "explanation": explanation + "選 A。"}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公開學校理化科資料僅供原子排列、元素特性、金屬性質與模型判讀的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公開學校理化科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "鑽石與石墨都只由碳元素組成，但硬度與導電性明顯不同。最合理的解釋是？", {"A": "碳原子的排列方式與彼此作用不同", "B": "鑽石含有另一種未被發現的元素", "C": "石墨的碳原子比較輕", "D": "兩者其實是不同元素的化合物"}, "元素種類相同不保證原子排列和作用方式相同；結構差異會造成巨觀性質差異。", "先確認組成元素，再把性質差異連回粒子排列與作用。", ["找出兩種材料共同的元素組成。", "比較題目指出的硬度與導電性差異。", "判斷只改變元素種類是否能解釋差異。", "改用原子排列與彼此作用方式說明結構—性質關係。", "所以選 A。"], "medium"),
    make(2, "用鉛筆在紙上留下黑色痕跡，較能支持石墨具有哪一項微觀特徵？", {"A": "石墨層與層之間容易滑動，少量碳層可脫離", "B": "石墨中的碳原子會全部變成氣體", "C": "石墨是由許多不同元素隨機混合", "D": "石墨的每一層都像鑽石一樣形成三度空間網狀"}, "鉛筆芯中的石墨可留下痕跡，表示部分薄層能在摩擦時移動或剝落；這符合層狀結構的解釋。", "把生活觀察先轉成可檢驗的結構假設，再排除與現象矛盾的模型。", ["辨認觀察到的是摩擦後留下固體痕跡。", "這表示材料中有部分微小層片能脫離。", "比較層間滑動與三度空間緊密連結的差異。", "層間較易滑動能解釋石墨可作書寫材料。", "所以選 A。"], "medium"),
    make(3, "若要解釋鑽石非常堅硬，哪一項模型最合適？", {"A": "碳原子以強作用連成延伸的三度空間網狀結構", "B": "碳原子只在平面薄層內弱弱吸引", "C": "鑽石中完全沒有原子間作用力", "D": "鑽石的硬度只由顏色深淺決定"}, "鑽石的碳原子形成延伸的三度空間網狀連結，外力不易讓整體結構滑移，因此可解釋高硬度。", "將硬度理解為結構抵抗形變的能力，不把顏色或重量當成直接原因。", ["把硬度翻成材料抵抗刮擦與形變的能力。", "檢查模型中原子是否有跨三度空間的連結。", "判斷外力能否讓整片結構容易滑動。", "強連結且不易滑移的網狀模型最能對應現象。", "所以選 A。"], "medium"),
    make(4, "銅線可導電且能被拉成細線。用粒子模型說明時，哪個組合最合理？", {"A": "金屬內有可移動的電子，原子層間也能在一定程度滑移", "B": "銅線內完全沒有帶電粒子", "C": "銅原子只能固定在單一位置，不能發生任何形變", "D": "銅能導電是因為它由水分子組成"}, "金屬導電可用可移動電子說明，能拉成線則表示結構在不立即斷裂下可發生形變；A 同時涵蓋兩個證據。", "逐一對應導電性與延展性，避免用單一性質解釋全部現象。", ["把導電性對應到電荷能否移動。", "把延展性對應到材料受力後能否變形。", "檢查選項是否同時說明兩個觀察。", "金屬的可移動電子與可形變結構分別對應兩者。", "所以選 A。"], "hard"),
    make(5, "元素符號 C 只能告訴我們樣品由哪種元素組成，不能單獨告訴我們什麼？", {"A": "碳原子在固體中的排列方式與材料的全部巨觀性質", "B": "樣品含有碳元素", "C": "樣品的主要元素符號可寫成 C", "D": "樣品和其他碳材料可能有共同元素"}, "元素符號表示元素種類，不足以單獨決定原子排列、鍵結方式或所有巨觀性質；鑽石與石墨就是例子。", "先區分化學身分的符號資訊與結構—性質資訊。", ["讀取 C 所代表的元素種類。", "列出元素符號沒有直接提供的結構資訊。", "用鑽石與石墨的反例檢查是否可由 C 唯一預測性質。", "同一元素可有不同排列與性質。", "所以選 A。"], "easy"),
    make(6, "甲、乙都是只含碳的固體。甲可導電且容易剝落薄片，乙不導電且難以刮傷。哪個推論最恰當？", {"A": "甲較可能具有層狀排列，乙較可能具有不易滑移的立體連結", "B": "甲一定不是碳，乙一定是金屬", "C": "兩者必然是同一種排列，只是溫度不同", "D": "只要知道顏色就能確定兩者的原子排列"}, "導電與易剝落可與層狀結構及較易移動的電子對應；不導電且堅硬則較符合不易滑移的立體連結，但仍是依證據提出的合理模型。", "使用『性質—模型』配對並保留證據能支持的程度，不把推論說成直接觀測。", ["整理甲的導電與易剝落證據。", "整理乙的不導電與難刮傷證據。", "分別配對層狀與立體網狀模型。", "檢查其他選項是否把元素、顏色或溫度過度簡化。", "所以選 A。"], "hard"),
    make(7, "下列哪一項最能提醒我們『模型不是實物照片』？", {"A": "模型的球形、顏色與間距是為了表示種類和關係，不必解讀成原子的真實外觀與比例", "B": "模型中的每個球都必須和真實原子一樣大", "C": "模型顏色就是原子真正呈現的顏色", "D": "模型畫得越大，原子在物質中就越大"}, "粒子模型把不可直接看見的粒子與排列轉成可視化符號，顏色、球大小和距離常是表徵，不是實物的直接照片。", "先說明模型要表達的變項，再指出不能由圖形外觀過度推論的部分。", ["確認模型的功能是表示粒子與關係。", "分辨符號化顏色和真實外觀。", "分辨示意球大小和真實原子半徑。", "把可由模型支持的結構關係與不可支持的比例分開。", "所以選 A。"], "easy"),
    make(8, "某金屬樣品的導電性下降，但仍可拉成線。下列哪種說法最符合科學推論？", {"A": "導電相關的電子移動受到影響，但整體結構仍保有可形變性", "B": "只要導電性下降，樣品就不可能是金屬", "C": "延展性與導電性永遠由同一個單一因素決定", "D": "導電性下降表示所有原子都消失了"}, "導電性與延展性是不同可觀察性質，前者變化不必讓後者同時消失；應分別提出對電子移動與結構形變的解釋。", "避免把多項巨觀性質硬綁成單一判準，逐項處理證據。", ["讀出題目只指出導電性下降。", "確認延展性仍保留，不能宣稱整體結構崩解。", "把導電性連到電子移動，把延展性連到結構可形變。", "檢查推論是否超出題目證據。", "所以選 A。"], "hard"),
    make(9, "若兩種只含同一元素的材料具有不同熔點，最適合的下一步研究是？", {"A": "比較它們的原子排列、連結方式與可能的結構差異", "B": "直接宣布其中一種一定含有另一種元素", "C": "只測量顏色，不必研究結構", "D": "把熔點差異視為測量錯誤而不查證"}, "熔點差異是結構—性質關係的線索，但不能單獨證明成分不同；應進一步比較排列和連結方式並用其他證據查驗。", "區分觀察、假設與驗證，避免由單一結果跳到過度結論。", ["把不同熔點列為觀察結果。", "確認兩材料已知含同一元素。", "提出排列或連結方式不同的可檢驗假設。", "規劃結構與其他性質的比較來交叉驗證。", "所以選 A。"], "medium"),
    make(10, "同素異形體的學習最能支持哪個科學概念？", {"A": "物質的性質取決於組成，也取決於粒子如何排列與彼此作用", "B": "只要元素符號相同，所有性質必定完全相同", "C": "巨觀性質與微觀結構沒有關係", "D": "不同排列代表一定有不同元素"}, "同素異形體共享元素種類，卻可能因排列與作用不同而呈現不同性質；這正是由微觀結構解釋巨觀現象的例子。", "用『組成相同、結構不同、性質不同』三段關係檢查選項。", ["確認同素異形體共享元素種類。", "確認它們的排列或連結方式可不同。", "把結構差異連到硬度、導電或熔點等性質。", "排除把元素符號當成全部性質的錯誤說法。", "所以選 A。"], "easy"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
